const built = new Map();
const mk = o => {
const base = o.b ? built.get(o.b) : null, meta = o.k === 'm' || o.k === 'nm';
const m = {
id: o.id, name: o.n, formula: o.f ?? null, kind: KIND[o.k], classId: o.c, dimensionality: o.d ?? null, description: o.t,
origin: meta ? (o.o || 'architected') : null, constituent: o.b ?? null,
props: base && !o.p ? { ...base.props } : P(o.p || {}),
effective: o.e ?? null, crystal: o.x ?? null, architecture: o.a ? { type: o.a[0], dims: o.a[1] } : null,
synthesis: o.s, applications: o.u, hazards: o.h, suites: o.su || CLASS_BY[o.c].suites,
search: { pubchem: o.pc ?? null, terms: o.q },
};
built.set(m.id, m); return m;
};
export const MATERIALS = [...CONS.map(mk), ...NANO.map(mk), ...META.map(mk)];
export function findMaterial(id) { return built.get(id) || null; }
export function findClass(id) { return CLASS_BY[id] || null; }
